type Obj = { [k: string]: unknown }
const isObj = (v: unknown): v is Obj => typeof v === "object" && v !== null && !Array.isArray(v)
function deepMerge(a: Obj, b: Obj): Obj {
    const out: Obj = { ...a }
    for (const [k, v] of Object.entries(b)) out[k] = isObj(v) && isObj(out[k]) ? deepMerge(out[k] as Obj, v) : v
    return out
}
console.log(JSON.stringify(deepMerge({ db: { host: "localhost", port: 5432 }, debug: false }, { db: { port: 6543 }, debug: true })))

