type Json = string | number | boolean | null | Json[] | { [k: string]: Json }
function sumNumbers(j: Json): number {
    if (typeof j === "number") return j
    if (Array.isArray(j)) return j.reduce<number>((s, x) => s + sumNumbers(x), 0)
    if (j && typeof j === "object") return Object.values(j).reduce<number>((s, x) => s + sumNumbers(x), 0)
    return 0
}
