const rules: Record<string, (value: string) => boolean> = {
    email: v => v.includes("@"),
    phone: v => /^\+998\d{9}$/.test(v),
}

function validate(field: string, value: string): boolean {
    const rule = rules[field]
    return rule ? rule(value) : false      // noma'lum maydon uchun qoida yo'q
}

console.log(validate("email", "ali@mail.uz"))
console.log(validate("phone", "+998901234567"))
console.log(validate("zip", "100000"))

function isRecord(value: unknown): value is Record<string, unknown> {
    return typeof value === "object" && value !== null && !Array.isArray(value)
}

const inputs: unknown[] = [{ name: "Ali" }, [1, 2], null, "matn", { name: 42 }]

for (const input of inputs) {
    if (isRecord(input) && typeof input.name === "string") console.log("ism:", input.name)
    else console.log("mos emas")
}
